import { useRef } from 'react';
import { useModal } from './useModal';

const KEYS: [string, string][] = [
  ['A / ←', 'Steer (hold): the bow to port; with tiller steering, the tiller to port, so the bow goes to starboard'],
  ['D / →', 'Steer the other way (hold). Bow or tiller steering: Settings → All settings → Controls'],
  ['Shift (held)', 'Hold the helm where it is (no self-centring)'],
  ['Space', 'Centre the helm'],
  ['W / ↑', 'Trim (pull in) the mainsheet'],
  ['S / ↓', 'Ease the mainsheet'],
  ['E / Q', 'Trim / ease the jib sheet'],
  ['M / J', 'Toggle auto-trim assist for main / jib'],
  ['K', 'Toggle auto crew weight'],
  ['X', 'Release both sheets (sails luff; head to wind as well to stop)'],
  ['Z / Shift+Z', 'Flatten the sails (depower) / power them up again, a quarter at a time'],
  ['O', 'Spinnaker: call for it to be hoisted, or dropped (the crew do it, in a few seconds); game controller: d-pad up'],
  ['I', 'Spinnaker: call for the crew to gybe the pole to the other side; game controller: d-pad down'],
  ['Home', 'Main menu: learn, sail freely, race or choose a scenario (the sail waits while it is open)'],
  ['P', 'Pause / resume'],
  ['R', 'Reset to the scenario start'],
  ['C', 'Cycle camera: chase (the wheel zooms), scenic, helm (drag to look around), orbit, drone, top'],
  ['T (hold)', 'Look up at the masthead: the burgee (or vane) there shows the wind you sail by; let go to look back (chase, helm and orbit views)'],
  ['U', 'Sound on or off (levels: Settings → All settings → Sound)'],
  ['B', 'Drone view: fly back to the boat'],
  ['F', 'Show physics force arrows'],
  ['G', 'Show the physics debug panel'],
  ['V', 'Validation dashboard (live charts, table, CSV export)'],
  ['L / N', 'Place labels / minimap'],
  ['Esc', 'Close the open panels and menus'],
  ['H or ?', 'This help'],
];

export function Help({ onClose, onTutorial, build }: { onClose: () => void; onTutorial: () => void; build?: { id: string; time: string } }) {
  const ref = useRef<HTMLDivElement>(null);
  useModal(ref, onClose);
  return (
    <div ref={ref} className="overlay" role="dialog" aria-modal="true" aria-label="Help" onClick={onClose}>
      <section className="panel help" onClick={(e) => e.stopPropagation()}>
        <div className="row left help-top">
          <button className="primary" onClick={onTutorial} autoFocus>Start a lesson</button>
          <span className="fine">A step-by-step lesson: steer, trim, tack, gybe and stop (about 5 minutes).</span>
        </div>
        <h3>How to sail</h3>
        <p>
          You helm a National Squib. Sail angle is set by the sheet: the sail blows out until the sheet stops it.
          Too far out and it luffs (no drive); too far in and it stalls. Watch the status chips under the sails.
          To tack, steer through the wind keeping speed; to stop, release the sheets and head into the wind.
        </p>
        <table>
          <tbody>{KEYS.map(([k, d]) => <tr key={k}><td className="key">{k}</td><td>{d}</td></tr>)}</tbody>
        </table>
        <h3>Your Squib</h3>
        <p>
          In Conditions → Boat, choose a Rondar (the modern standard: its cockpit drains itself), a classic Hunter or Parker
          hull (water that comes over the rail stays until your crew bails it, so keep the rail out of the water), or the
          new Hyde B3 / Batt sails. The burgee at the masthead shows the apparent wind. With wind against tide, as in the
          harbour entrance on the ebb, expect short, steep waves; More instruments shows the waves.
        </p>
        <h3>The spinnaker</h3>
        <p>
          In races, and when free sailing at Club and Expert, your Squib carries her spinnaker. Call for it with O (or the
          Hoist button) once the wind is well behind the beam: the crew hoist it on its pole and trim it, and it pulls the
          boat faster. If the wind comes too far forward, or the pole is on the wrong side after a gybe, it collapses; press I
          to have the pole gybed (the crew do this themselves after a gybe when they trim it). Drop it (O again) before
          you round a mark onto a beat: dropping takes a few seconds. At Expert, Sails… lets you trim it by hand and set the
          kicker, cunningham, outhaul and jib lead one by one. Its figures are estimates (docs/PHYSICS.md §23).
        </p>
        <h3>Racing</h3>
        <p>
          In Conditions, choose a course and up to 20 AI boats (or use Race for a quick race). Watch the flags: class flag at the warning signal, P (or U,
          black) at the preparatory signal, coming down at one minute; the start when the class flag comes down. Flag X:
          someone was over early (return behind the line); First Substitute: general recall. Port tack keeps clear of
          starboard, windward of leeward, clear astern of clear ahead, and a boat tacking keeps clear. If you hit a boat
          you should have kept clear of, take a Two-Turns Penalty (two turns the same way, each with a tack and a gybe);
          for touching a mark, one turn. The judge is a simplified subset of the racing rules, not an authoritative one.
        </p>
        <p className="fine">
          On the River Dart: terrain, buildings, piers and the shoreline come from open data; water
          depths mid-channel, individual moorings, most ferry timetables, vessel sizes, roof shapes and the tidal stream are
          provisional estimates (see Layers). You can run aground: the keel stops you in shallow water, and moored boats,
          ferries and the boats leaving Dart Marina are solid. The boat heels dynamically, the boom swings on its own and can gybe
          unexpectedly by the lee, and the wind has seeded gusts and shifts (dark patches on the water are puffs).
          Boat dimensions are from class sources; hydrodynamic and sail coefficients are estimates awaiting
          calibration. Weather and tide sources are labelled in the instruments. Not for navigation or performance
          prediction.
        </p>
        {build && (
          <p className="fine" data-testid="build-stamp">
            This build: {build.id}, made {build.time}.
          </p>
        )}
        <button className="primary" onClick={onClose}>Close</button>
      </section>
    </div>
  );
}
